// Generated by AI
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Automatically discovers child characters under Player and cycles between them
/// without manual slot or SpriteRenderer setup in the Inspector.
/// </summary>
public class SimpleCharacterSwitcher : MonoBehaviour
{
    [Header("Switch Settings")]
    [SerializeField] private KeyCode cycleKey = KeyCode.Q;
    [SerializeField] private int startingCharacterIndex = 0;
    [SerializeField] private AudioClip switchSound;

    private readonly List<GameObject> characterObjects = new List<GameObject>();
    private readonly List<Animator> characterAnimators = new List<Animator>();
    private readonly List<SpriteRenderer> characterSprites = new List<SpriteRenderer>();

    private PlayerController playerController;
    private PlayerHealthAndRespawn healthAndRespawn;
    private int currentIndex = 0;

    private void Awake()
    {
        playerController = GetComponent<PlayerController>();
        healthAndRespawn = GetComponent<PlayerHealthAndRespawn>();

        CacheChildCharacters();
    }

    private void Start()
    {
        if (characterObjects.Count == 0)
        {
            Debug.LogWarning("No child characters with Animator found under Player.");
            return;
        }

        currentIndex = Mathf.Clamp(startingCharacterIndex, 0, characterObjects.Count - 1);
        ApplyCharacter(currentIndex, playAudio: false);
    }

    private void Update()
    {
        if (characterObjects.Count <= 1)
            return;

        if (Input.GetKeyDown(cycleKey))
        {
            int nextIndex = (currentIndex + 1) % characterObjects.Count;
            ApplyCharacter(nextIndex, playAudio: true);
        }
    }

    private void CacheChildCharacters()
    {
        characterObjects.Clear();
        characterAnimators.Clear();
        characterSprites.Clear();

        for (int i = 0; i < transform.childCount; i++)
        {
            Transform child = transform.GetChild(i);
            Animator anim = child.GetComponentInChildren<Animator>(true);

            // Only include character children that have an Animator (skips helper objects like GroundCheck)
            if (anim != null)
            {
                characterObjects.Add(child.gameObject);
                characterAnimators.Add(anim);
                characterSprites.Add(child.GetComponentInChildren<SpriteRenderer>(true));
            }
        }
    }

    private void ApplyCharacter(int index, bool playAudio)
    {
        currentIndex = index;

        for (int i = 0; i < characterObjects.Count; i++)
        {
            characterObjects[i].SetActive(i == currentIndex);
        }

        Animator activeAnimator = characterAnimators[currentIndex];
        SpriteRenderer activeSprite = characterSprites[currentIndex];

        if (playerController != null)
        {
            if (activeAnimator != null)
            {
                playerController.characterAnimator = activeAnimator;
            }

            if (activeSprite != null)
            {
                playerController.characterSprite = activeSprite;
            }
        }

        if (healthAndRespawn != null && activeAnimator != null)
        {
            healthAndRespawn.characterAnimator = activeAnimator;
        }

        if (playAudio && AudioManager.Instance != null && switchSound != null)
        {
            AudioManager.Instance.PlaySFX(switchSound);
        }
    }
}